using Microsoft.ML.Data;

namespace TicketClassifier.Models;

public sealed class TicketData
{
    [LoadColumn(0)]
    public string Subject { get; set; } = string.Empty;

    [LoadColumn(1)]
    public string Description { get; set; } = string.Empty;

    [LoadColumn(2)]
    public float Priority { get; set; }

    [LoadColumn(3)]
    public string Category { get; set; } = string.Empty;
}

public sealed class TicketPrediction
{
    [ColumnName("PredictedLabel")]
    public string Category { get; set; } = string.Empty;

    public float[] Score { get; set; } = [];
}

namespace TicketClassifier.Models;

public sealed class TicketRequest
{
    public string Subject { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Priority { get; set; }
}

public sealed class TicketPredictionResponse
{
    public string PredictedCategory { get; set; } = string.Empty;
    public Dictionary<string, float> Confidences { get; set; } = new();
}

using Microsoft.ML;
using Microsoft.ML.Data;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public sealed class TicketModelService
{
    private readonly MLContext _mlContext;
    private readonly ITransformer _model;
    private readonly PredictionEngine<TicketData, TicketPrediction> _predictionEngine;
    private readonly ILogger<TicketModelService> _logger;

    public string[] Labels { get; }
    public MulticlassClassificationMetrics Metrics { get; }

    public TicketModelService(ILogger<TicketModelService> logger)
    {
        _logger = logger;
        _mlContext = new MLContext(seed: 0);

        var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "tickets.csv");
        var dataView = _mlContext.Data.LoadFromTextFile<TicketData>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        // Use the full dataset for both training and evaluation given the small size.
        // With only 6 rows, a train/test split would leave too few samples for meaningful
        // evaluation. In production, use TrainTestSplit once more data is available.
        (_model, Metrics) = TrainAndEvaluate(dataView, dataView);

        _predictionEngine = _mlContext.Model.CreatePredictionEngine<TicketData, TicketPrediction>(_model);

        var labelBuffer = new VBuffer<ReadOnlyMemory<char>>();
        _predictionEngine.OutputSchema["Score"]
            .GetSlotNames(ref labelBuffer);
        Labels = labelBuffer.DenseValues().Select(v => v.ToString()).ToArray();

        LogMetrics();
    }

    private (ITransformer model, MulticlassClassificationMetrics metrics) TrainAndEvaluate(
        IDataView trainData, IDataView testData)
    {
        // Combine Subject + Description into a single text feature, then featurize
        var pipeline = _mlContext.Transforms.Conversion
                .MapValueToKey("Label", nameof(TicketData.Category))
            .Append(_mlContext.Transforms.Text.FeaturizeText(
                "SubjectFeaturized", nameof(TicketData.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText(
                "DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(_mlContext.Transforms.Concatenate(
                "Features", "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(_mlContext.Transforms.NormalizeMinMax("Features"))
            .Append(_mlContext.MulticlassClassification.Trainers
                .SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion
                .MapKeyToValue("PredictedLabel"));

        var model = pipeline.Fit(trainData);
        var predictions = model.Transform(testData);
        var metrics = _mlContext.MulticlassClassification.Evaluate(predictions);

        return (model, metrics);
    }

    private void LogMetrics()
    {
        _logger.LogInformation("===== Ticket Classifier Evaluation =====");
        _logger.LogInformation("Macro Accuracy:    {MacroAccuracy:F4}", Metrics.MacroAccuracy);
        _logger.LogInformation("Micro Accuracy:    {MicroAccuracy:F4}", Metrics.MicroAccuracy);
        _logger.LogInformation("Log Loss:          {LogLoss:F4}", Metrics.LogLoss);
        _logger.LogInformation("Log Loss Reduction:{LogLossReduction:F4}", Metrics.LogLossReduction);
        _logger.LogInformation("========================================");
    }

    public TicketPredictionResponse Predict(TicketRequest request)
    {
        var input = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionEngine.Predict(input);

        var confidences = new Dictionary<string, float>();
        for (var i = 0; i < Labels.Length; i++)
        {
            confidences[Labels[i]] = prediction.Score[i];
        }

        return new TicketPredictionResponse
        {
            PredictedCategory = prediction.Category,
            Confidences = confidences
        };
    }
}

using Microsoft.AspNetCore.Mvc;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public class TicketClassifierController : ControllerBase
{
    private readonly TicketModelService _modelService;

    public TicketClassifierController(TicketModelService modelService)
    {
        _modelService = modelService;
    }

    /// <summary>Predict the category for a support ticket.</summary>
    [HttpPost("predict")]
    public ActionResult<TicketPredictionResponse> Predict([FromBody] TicketRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Subject) && string.IsNullOrWhiteSpace(request.Description))
            return BadRequest("Subject or Description is required.");

        if (request.Priority is < 1 or > 3)
            return BadRequest("Priority must be between 1 and 3.");

        return Ok(_modelService.Predict(request));
    }

    /// <summary>Return model evaluation metrics.</summary>
    [HttpGet("metrics")]
    public IActionResult GetMetrics()
    {
        var m = _modelService.Metrics;
        return Ok(new
        {
            m.MacroAccuracy,
            m.MicroAccuracy,
            m.LogLoss,
            m.LogLossReduction,
            PerClassLogLoss = m.PerClassLogLoss.ToArray()
        });
    }
}

